import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Color palette
  const colors = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
  };

  // Load brushed metal roughness map
  const roughnessMap = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  roughnessMap.wrapS = THREE.RepeatWrapping;
  roughnessMap.wrapT = THREE.RepeatWrapping;

  // Create scratch-noise normal map via DataTexture
  function createScratchNormalMap() {
    const size = 512;
    const data = new Uint8Array(size * size * 4);

    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.random() * 0.15;
      data[i] = Math.floor(128 + noise * 127);
      data[i + 1] = Math.floor(128 + noise * 127);
      data[i + 2] = 255;
      data[i + 3] = 255;
    }

    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.UnsignedByteType);
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.needsUpdate = true;
    return texture;
  }

  // Create radial shadow gradient texture
  function createShadowTexture() {
    const size = 256;
    const data = new Uint8Array(size * size * 4);

    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const idx = (y * size + x) * 4;
        const dx = x - size / 2;
        const dy = y - size / 2;
        const dist = Math.sqrt(dx * dx + dy * dy) / (size / 2);
        const alpha = Math.max(0, (1 - dist) * 0.6);

        data[idx] = 0;
        data[idx + 1] = 0;
        data[idx + 2] = 0;
        data[idx + 3] = Math.floor(alpha * 255);
      }
    }

    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.UnsignedByteType);
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.needsUpdate = true;
    return texture;
  }

  // Create vertical gradient backdrop texture
  function createBackdropTexture() {
    const size = 512;
    const data = new Uint8Array(size * size * 4);

    const stops = [
      { at: 0, color: [0x0b, 0x0b, 0x10] },
      { at: 0.7, color: [0x10, 0x10, 0x17] },
      { at: 1, color: [0x16, 0x16, 0x1d] },
    ];

    for (let y = 0; y < size; y++) {
      const t = y / size;

      let c1, c2, t1, t2;
      for (let i = 0; i < stops.length - 1; i++) {
        if (t >= stops[i].at && t <= stops[i + 1].at) {
          t1 = stops[i].at;
          t2 = stops[i + 1].at;
          c1 = stops[i].color;
          c2 = stops[i + 1].color;
          break;
        }
      }

      const localT = (t - t1) / (t2 - t1);
      const r = Math.floor(c1[0] + (c2[0] - c1[0]) * localT);
      const g = Math.floor(c1[1] + (c2[1] - c1[1]) * localT);
      const b = Math.floor(c1[2] + (c2[2] - c1[2]) * localT);

      for (let x = 0; x < size; x++) {
        const idx = (y * size + x) * 4;
        data[idx] = r;
        data[idx + 1] = g;
        data[idx + 2] = b;
        data[idx + 3] = 255;
      }
    }

    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat, THREE.UnsignedByteType);
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.needsUpdate = true;
    return texture;
  }

  const scratchNormalMap = createScratchNormalMap();
  const shadowTexture = createShadowTexture();
  const backdropTexture = createBackdropTexture();

  // TORUS KNOT: radius 0.7, tube 0.22, 220x36 segments, brushed metal PBR
  const torusKnotGeometry = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);

  const torusKnotMaterial = new THREE.MeshStandardMaterial({
    color: colors.ink,
    metalness: 0.55,
    roughness: 0.55,
    roughnessMap,
    normalMap: scratchNormalMap,
    normalScale: new THREE.Vector2(0.15, 0.15),
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });

  const torusKnotMesh = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
  torusKnotMesh.position.set(0, 0.4, 0);
  torusKnotMesh.castShadow = true;
  torusKnotMesh.receiveShadow = true;
  group.add(torusKnotMesh);

  // PEDESTAL: radius 1.1, height 0.5, top face at y=-0.35
  const pedestalGeometry = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64);

  const pedestalMaterial = new THREE.MeshStandardMaterial({
    color: colors.surface,
    roughness: 0.7,
    metalness: 0.35,
  });

  const pedestalMesh = new THREE.Mesh(pedestalGeometry, pedestalMaterial);
  pedestalMesh.position.y = -0.35;
  pedestalMesh.castShadow = true;
  pedestalMesh.receiveShadow = true;
  group.add(pedestalMesh);

  // CONTACT SHADOW: radial gradient plane, radius 1.5, at y=-0.36
  const shadowGeometry = new THREE.PlaneGeometry(3, 3);

  const shadowMaterial = new THREE.MeshBasicMaterial({
    map: shadowTexture,
    transparent: true,
    depthWrite: false,
  });

  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.position.set(0, -0.36, 0.01);
  shadowMesh.scale.set(1.5, 1.5, 1);
  group.add(shadowMesh);

  // BACKDROP: 7x6 plane at z=-3 with vertical gradient
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);

  const backdropMaterial = new THREE.MeshBasicMaterial({
    map: backdropTexture,
  });

  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.z = -3;
  group.add(backdropMesh);

  // TEXT CONTENT via fontAtlas
  const textContent = config.textContent || {};

  if (textContent.headline) {
    const headlineMesh = ctx.fontAtlas.create(textContent.headline, {
      family: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: colors.paper,
    });
    headlineMesh.position.set(0, -1.2, 0.5);
    group.add(headlineMesh);
  }

  if (textContent.caption) {
    const captionMesh = ctx.fontAtlas.create(textContent.caption, {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: colors.paper,
    });
    captionMesh.position.set(0, -1.6, 0.5);
    group.add(captionMesh);
  }

  // LIGHTING: studio PMREM IBL at intensity 0.7
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
  group.add(ambientLight);

  const keyLight = new THREE.DirectionalLight(0xffffff, 0.8);
  keyLight.position.set(2, 2, 2);
  keyLight.castShadow = true;
  group.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
  fillLight.position.set(-1, 0.5, 1);
  group.add(fillLight);

  // APPLY CINEMATIC PRIMITIVES: orbit animation on torus knot
  if (ctx.primitives && ctx.primitives.orbit) {
    ctx.primitives.orbit(torusKnotMesh, { speed: 0.1, radius: 0.4 });
  }

  // CLEANUP: dispose all resources and kill GSAP timelines
  group.userData.cleanup = () => {
    torusKnotGeometry.dispose();
    pedestalGeometry.dispose();
    shadowGeometry.dispose();
    backdropGeometry.dispose();

    torusKnotMaterial.dispose();
    pedestalMaterial.dispose();
    shadowMaterial.dispose();
    backdropMaterial.dispose();

    roughnessMap.dispose();
    scratchNormalMap.dispose();
    shadowTexture.dispose();
    backdropTexture.dispose();

    gsap.killTweensOf(torusKnotMesh.position);
    gsap.killTweensOf(torusKnotMesh.rotation);
  };

  return group;
}
